<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class ProjectBudget extends Model { use \App\Traits\HasCompany; public const STATUSES=['draft','pending_approval','approved','superseded','closed','cancelled']; protected $attributes=['status'=>'draft']; protected $fillable=['company_id','project_id','version_number','name','notes']; protected $casts=['submitted_at'=>'datetime','approved_at'=>'datetime','closed_at'=>'datetime']; public function project():BelongsTo{return $this->belongsTo(Project::class);} public function categories():HasMany{return $this->hasMany(BudgetCategory::class);} public function items(){return $this->hasManyThrough(BudgetItem::class,BudgetCategory::class,'project_budget_id','budget_category_id');} public function roots():HasMany{return $this->categories()->whereNull('parent_id');} public function submittedBy():BelongsTo{return $this->belongsTo(User::class,'submitted_by');} public function approvedBy():BelongsTo{return $this->belongsTo(User::class,'approved_by');} }
